[CmdletBinding()]param([Parameter(Mandatory=$true)][ValidateSet('Offer','Accept','Activate','Suspend','Revoke','Archive','Validate')][string]$Action,[Parameter(Mandatory=$true)][string]$TransferPath,[string]$SpaceId,[string]$FromOwnerId,[string]$ToOwnerId,[string[]]$PermissionScope=@('ReadMetadata'),[int]$ExpectedRevision=0,[string]$Reason='',[datetime]$EffectiveAtUtc=(Get-Date).ToUniversalTime(),[Nullable[datetime]]$ExpiresAtUtc=$null)
$ErrorActionPreference='Stop';$utf8=[Text.UTF8Encoding]::new($false,$true);$next=@{Offer='Offered';Accept='Accepted';Activate='Active';Suspend='Suspended';Revoke='Revoked';Archive='Archived'};$allowed=@{Offered=@('Accepted','Revoked');Accepted=@('Active','Revoked');Active=@('Suspended','Revoked');Suspended=@('Active','Revoked');Revoked=@('Archived');Archived=@()};function ReadJ($p){$utf8.GetString([IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $p).Path))|ConvertFrom-Json};function WriteNew($p,$v){if(Test-Path $p){throw "ReceiptAlreadyExists:$p"};[IO.Directory]::CreateDirectory((Split-Path $p))|Out-Null;[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 12),$utf8)};function HashJ($v){$c=$v|ConvertTo-Json -Depth 12|ConvertFrom-Json;$c.receiptHash=$null;$h=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes(($c|ConvertTo-Json -Depth 12 -Compress)))).Replace('-','')).ToLowerInvariant()}finally{$h.Dispose()}};function Id($v){if($v -notmatch '^[a-f0-9]{32}$'){throw 'InvalidId'}}
if($Action -eq 'Offer'){$null=Id $SpaceId;if([string]::IsNullOrWhiteSpace($FromOwnerId)-or[string]::IsNullOrWhiteSpace($ToOwnerId)-or[string]::IsNullOrWhiteSpace($Reason)){throw 'TransferFieldsRequired'};$exp=$null;if($null -ne $ExpiresAtUtc){$exp=$ExpiresAtUtc.ToUniversalTime().ToString('O')};$r=[ordered]@{schemaVersion=1;transferId=([Guid]::NewGuid().ToString('N'));spaceId=$SpaceId;fromOwnerId=$FromOwnerId;toOwnerId=$ToOwnerId;permissionScope=@($PermissionScope);state='Offered';expectedRevision=1;effectiveAtUtc=$EffectiveAtUtc.ToUniversalTime().ToString('O');expiresAtUtc=$exp;reason=$Reason;previousReceiptHash=('0'*64);receiptHash=''};$r.receiptHash=HashJ $r;WriteNew $TransferPath $r;Write-Output $TransferPath;exit}
$r=ReadJ $TransferPath;Id $r.transferId;Id $r.spaceId;if($Action -eq 'Validate'){if([string]$r.receiptHash -ne (HashJ $r)){throw 'ReceiptHashMismatch'};$rs=@(Get-ChildItem (Split-Path $TransferPath) -Filter ($r.transferId+'-receipt-*.json') -File|Sort Name);$prior=$null;foreach($f in $rs){$q=ReadJ $f.FullName;if($q.transferId -ne $r.transferId -or $q.spaceId -ne $r.spaceId){throw 'ReceiptBindingMismatch'};if($null -ne $prior -and $q.previousReceiptHash -ne $prior){throw 'ReceiptChainMismatch'};$prior=$q.receiptHash};if($rs.Count -gt 0 -and $prior -ne $r.receiptHash){throw 'LatestReceiptMismatch'};[pscustomobject]@{status='passed';state=$r.state;revision=$r.expectedRevision;receipts=$rs.Count;runtimeStatus='runtime-not-run'}|ConvertTo-Json -Compress;exit}
if($ExpectedRevision -lt 1-or[int]$r.expectedRevision -ne $ExpectedRevision){throw "RevisionConflict:$($r.expectedRevision)"};$from=$r.state;$target=$next[$Action];if($null -eq $target-or -not $allowed[$r.state].Contains($target)){throw "IllegalTransition:$($r.state)->$target"};if($r.expiresAtUtc-and([DateTimeOffset]::UtcNow -gt [DateTimeOffset]$r.expiresAtUtc)){throw 'TransferExpired'};$prior=if([int]$r.expectedRevision -eq 1){('0'*64)}else{[string]$r.receiptHash};$r.state=$target;$r.expectedRevision=[int]$r.expectedRevision+1;$r.previousReceiptHash=$prior;$r.receiptHash='';$r.receiptHash=HashJ $r;$receipt=[ordered]@{schemaVersion=1;receiptId=([Guid]::NewGuid().ToString('N'));transferId=$r.transferId;spaceId=$r.spaceId;fromState=$from;toState=$target;revision=$r.expectedRevision;createdAtUtc=[DateTimeOffset]::UtcNow.ToString('O');reason=$r.reason;previousReceiptHash=$prior;receiptHash=$r.receiptHash};WriteNew ([IO.Path]::Combine((Split-Path $TransferPath),($r.transferId+'-receipt-'+$r.expectedRevision+'.json'))) $receipt;[IO.File]::WriteAllText($TransferPath,($r|ConvertTo-Json -Depth 12),$utf8);$r|ConvertTo-Json -Depth 12

# Canonical hash contract: fixed field order, invariant text, UTF-8 without BOM.
function HashJ($v){$canonical=@([string]$v.schemaVersion,[string]$v.transferId,[string]$v.spaceId,[string]$v.fromOwnerId,[string]$v.toOwnerId,(@($v.permissionScope)-join ','),[string]$v.state,[string]$v.expectedRevision,[string]$v.effectiveAtUtc,[string]$v.expiresAtUtc,[string]$v.reason,[string]$v.previousReceiptHash)-join "`n";$h=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($canonical))).Replace('-','')).ToLowerInvariant()}finally{$h.Dispose()}}
